import {resolveTakeSettings,takePresetChoices,takePropertyChoices,takeFlagChoices} from './take-settings.js';
const flagAttributes={includeComponents:'data-take-components',includeStructure:'data-take-structure',includeHierarchy:'data-take-hierarchy',includeSkeleton:'data-take-skeleton',includeVariables:'data-take-values',includeSpawned:'data-take-spawned',includeAudio:'data-take-audio'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(rows,value)=>rows.map(([id,label])=>'<option value="'+id+'" '+(id===value?'selected':'')+'>'+label+'</option>').join('');
export function takeSettingsMarkup(settings,recording){const disabled=recording?'disabled':'',checkbox=(attribute,key,label,checked)=>'<label><input type="checkbox" '+attribute+'="'+key+'" '+(attribute==='data-take-option'?flagAttributes[key]+' ':'')+(checked?'checked':'')+' '+disabled+'>'+label+'</label>';return '<label>프리셋<select data-take-preset '+disabled+'>'+options(takePresetChoices,settings.preset)+'</select></label><fieldset class="take-channel-filter"><legend>트랜스폼 채널</legend>'+takePropertyChoices.map(([key,label])=>checkbox('data-take-property',key,label,settings.properties.includes(key))).join('')+'</fieldset>'+takeFlagChoices.map(([key,label])=>checkbox('data-take-option',key,label,settings[key])).join('')+'<label '+(!settings.includeSkeleton?'hidden':'')+'>뼈 이름<input data-take-bones value="'+esc(settings.boneNames.join(', '))+'" '+disabled+' placeholder="전체"></label><fieldset class="take-spawn-filter" '+(!settings.includeSpawned?'hidden':'')+'><legend>생성 오브젝트 필터</legend><label>반경<input data-take-filter="radius" type="number" min="0" max="1000000000" step="any" value="'+settings.spawnFilter.radius+'" '+disabled+'></label><label>기준<select data-take-filter="center" '+disabled+'>'+options([['camera','카메라'],['targets','녹화 대상']],settings.spawnFilter.center)+'</select></label><label>평면<select data-take-filter="plane" '+disabled+'>'+options([['xyz','3D'],['xy','2D · XY'],['xz','2.5D · XZ']],settings.spawnFilter.plane)+'</select></label>'+[['kinds','오브젝트 종류'],['classes','C++ 클래스'],['components','필수 컴포넌트']].map(([key,label])=>'<label>'+label+'<input data-take-filter="'+key+'" value="'+esc(settings.spawnFilter[key].join(', '))+'" '+disabled+'></label>').join('')+'</fieldset>';}
export function takeSettingsInput(input,current,plane){
 if(input.hasAttribute('data-take-preset'))return input.value==='custom'?{...current,preset:'custom'}:resolveTakeSettings({preset:input.value},{plane});const next=structuredClone(current);next.preset='custom';const list=v=>[...new Set(v.split(',').map(s=>s.trim()).filter(Boolean))];
 if(input.dataset.takeOption)next[input.dataset.takeOption]=input.checked;
 else if(input.dataset.takeProperty){const set=new Set(next.properties);input.checked?set.add(input.dataset.takeProperty):set.delete(input.dataset.takeProperty);next.properties=takePropertyChoices.map(([key])=>key).filter(key=>set.has(key));}
 else if(input.hasAttribute('data-take-bones'))next.boneNames=list(input.value);
 else if(input.dataset.takeFilter){const key=input.dataset.takeFilter;next.spawnFilter[key]=key==='radius'?Number(input.value):['kinds','classes','components'].includes(key)?list(input.value):input.value;}
 else return null;return resolveTakeSettings(next,{plane});
}
